tool.expression:
{
        // Galaxy cannot declare a variable number of outputs, so the tool
        // exposes a fixed pool of slots and prunes the unused ones with
        // <filter> in <outputs>. The slot count, the <repeat max=""> and the
        // number of outputs all come from the @MAX_SLOTS@ token in macros.xml.
        var MAX_SLOTS = @MAX_SLOTS@;

        var FLOAT_PATTERN = /^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/;
        var INTEGER_PATTERN = /^[+-]?\d+$/;
        var TRUE_VALUES = ['true', 'yes', '1'];
        var FALSE_VALUES = ['false', 'no', '0'];
        var SUPPORTED_TYPES = ['float', 'integer', 'text', 'boolean'];

        function fail(message) {
            throw new Error(message);
        }

        function parseNumber(columnName, columnType, value) {
            var pattern = columnType === 'integer' ? INTEGER_PATTERN : FLOAT_PATTERN;
            if (!pattern.test(value)) {
                fail('Column "' + columnName + '": "' + value + '" is not a valid ' + columnType + ' value.');
            }
            // Number() alone is not enough: it accepts "", "Infinity" and
            // "1e400", the last two of which have no JSON representation.
            var parsed = Number(value);
            if (!isFinite(parsed)) {
                fail('Column "' + columnName + '": "' + value + '" is out of range.');
            }
            return parsed;
        }

        function parseBoolean(columnName, value) {
            var lowered = value.toLowerCase();
            if (TRUE_VALUES.indexOf(lowered) !== -1) {
                return true;
            }
            if (FALSE_VALUES.indexOf(lowered) !== -1) {
                return false;
            }
            // Anything else is an error rather than a silent false, because the
            // downstream tools use TRUE/False spellings interchangeably.
            fail('Column "' + columnName + '": "' + value + '" is not a boolean value; expected one of ' +
                 TRUE_VALUES.concat(FALSE_VALUES).join(', ') + ' (any case).');
        }

        function parseValue(columnName, columnType, rawValue) {
            var value = String(rawValue).trim();
            if (columnType === 'text') {
                return value;
            }
            if (value.length === 0) {
                fail('Column "' + columnName + '" is empty, but a ' + columnType + ' value is required.');
            }
            if (columnType === 'boolean') {
                return parseBoolean(columnName, value);
            }
            return parseNumber(columnName, columnType, value);
        }

        try {
            var columns = $job.columns;
            var rowIndex = $job.row_index;
            var delimiter = $job.delimiter === 'tab' ? '\t' : ',';

            if (!columns || columns.length === 0) {
                fail('At least one column has to be configured.');
            }
            if (columns.length > MAX_SLOTS) {
                fail('At most ' + MAX_SLOTS + ' columns are supported, but ' + columns.length + ' were configured.');
            }

            var configuredNames = [];
            var i;
            for (i = 0; i < columns.length; i++) {
                var name = String(columns[i].column_name).trim();
                var columnType = String(columns[i].column_type).trim();
                if (name.length === 0) {
                    fail('Column ' + (i + 1) + ' has no name.');
                }
                if (configuredNames.indexOf(name) !== -1) {
                    fail('Column name "' + name + '" is configured more than once.');
                }
                if (SUPPORTED_TYPES.indexOf(columnType) === -1) {
                    fail('Column "' + name + '" has the unsupported type "' + columnType + '".');
                }
                configuredNames.push(name);
            }

            var rawContents = $job.table.contents;
            if (typeof rawContents !== 'string') {
                fail('The contents of the input table could not be read. Make sure the file is not empty.');
            }

            var lines = rawContents.split('\n');
            var rows = [];
            for (i = 0; i < lines.length; i++) {
                rows.push(lines[i].replace(/\r$/, ''));
            }
            while (rows.length > 1 && rows[rows.length - 1].trim() === '') {
                rows.pop();
            }
            if (rows.length < 2) {
                fail('The input table needs a header row and at least one data row, but only ' + rows.length + ' row(s) were found.');
            }

            var header = [];
            var headerCells = rows[0].split(delimiter);
            for (i = 0; i < headerCells.length; i++) {
                header.push(headerCells[i].trim());
            }

            if (rowIndex < 1 || rowIndex >= rows.length) {
                fail('Row ' + rowIndex + ' does not exist. The table has ' + (rows.length - 1) +
                     ' data row(s); row numbering starts at 1 for the row below the header.');
            }
            var cells = rows[rowIndex].split(delimiter);

            // Only the used slots are returned: a slot whose <filter> kept the
            // output but whose value is missing is a bug, and failing loudly is
            // better than emitting a silently empty parameter.
            var result = {};
            for (i = 0; i < configuredNames.length; i++) {
                var wanted = configuredNames[i];
                var position = header.indexOf(wanted);
                if (position === -1) {
                    fail('Column "' + wanted + '" was not found in the header of the input table. Available columns: ' +
                         header.join(', '));
                }
                if (position >= cells.length) {
                    fail('Row ' + rowIndex + ' has no value for column "' + wanted +
                         '". The header has ' + header.length + ' columns but this row has only ' + cells.length + '.');
                }
                result['v_' + i] = parseValue(wanted, String(columns[i].column_type).trim(), cells[position]);
            }
            return result;
        } catch (error) {
            return {'__error_message': String(error.message || error)};
        }
    }
